import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DpI_zlPE.js";var i=JSON.parse(`{"title":"影像兼容颜料墨水","description":"","frontmatter":{},"headers":[],"relativePath":"ccc/色彩管理/兼容影像颜料墨水.md","filePath":"ccc/色彩管理/兼容影像颜料墨水.md"}`),a={name:`ccc/色彩管理/兼容影像颜料墨水.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="影像兼容颜料墨水" tabindex="-1">影像兼容颜料墨水 <a class="header-anchor" href="#影像兼容颜料墨水" aria-label="Permalink to “影像兼容颜料墨水”">​</a></h1><h2 id="兼容颜料特性" tabindex="-1">兼容颜料特性 <a class="header-anchor" href="#兼容颜料特性" aria-label="Permalink to “兼容颜料特性”">​</a></h2><p>1、黑灰墨水黑位不正，既爱普生原装黑灰墨水通常反射率光谱是直线，而兼容颜料，往往带点轻微的色度，通常泛红褐色，光谱反射率在660nm以上会翘曲。</p><blockquote><p>由于纸张本身往往带点色度，所以黑白打印，爱普生原装墨水也不是单纯只喷黑灰墨水，还是会稍微带点彩色墨点。但是如果只能进行RGB校色，我推测黑位不正对插值后的可靠度可能是有一定影响的。</p></blockquote><p>2、黑色墨水反光泛白（烫金效应）特别严重，爱普生原装墨水反光泛白比较自然，整体光感相近，而兼容颜料黑色墨水泛白特别严重。</p><p>3、黑色墨水黑位观感相对爱普生原装墨水有显著差距。</p><p>4、CMYK以外的专色如大红RED、蓝BLUE、绿GREEN、紫罗兰VIOLET等，较大概率是假把式，用CMYK勾兑，不扩展色域。</p><h3 id="最大短板" tabindex="-1">最大短板： <a class="header-anchor" href="#最大短板" aria-label="Permalink to “最大短板：”">​</a></h3><p>当下爱普生桌面机型都是ESC/PR协议，传输的是RGB位图数据，转换为实际喷墨墨点（RIP分色程序、喷墨程序）由打印机固件进行。</p><p>而通常进行的RGB校色只能改变传递给打印机的RGB值，是描述而非校准，既描述输出某个RGB值实际打印的色值。而兼容墨水由于不匹配打印程序，插值可靠度不如原装墨水，既同样校色的绝对色准，相对原装墨水有细微差距。</p><p>爱普生P708支持ESC/2协议，开源驱动Gutenprinter是可以强行打印的，但由于该驱动开发趋于停滞，所以没有适配爱普生P708，Violet墨没法用，粗面黑也没法用，要用的话，还需要自己开发配置，但没有傻瓜教程，比如进行CMYK线性化，LC、LM介入曲线、黑灰墨水的分配等，都没有傻瓜教程，甚至连测试图也没有。</p><p>爱普生P7080等大幅面机型，买一个EFI Fiery的盗版USB加密狗，装EFI Fiery RIP的Halftone CMYK（半色调CMYK）驱动，有傻瓜流程进行最大墨量、CMYK线性化的配置。可以最大程度的发挥兼容墨水的性能。但兼容颜料固有的几大短板，依旧无解。</p><h2 id="鸿盛鸿彩6" tabindex="-1">鸿盛鸿彩6 <a class="header-anchor" href="#鸿盛鸿彩6" aria-label="Permalink to “鸿盛鸿彩6”">​</a></h2><p><strong>务必审慎！务必审慎！务必审慎！</strong></p><p><strong>推测</strong>高树脂含量，可能有较大堵头风险。</p><p>在无反光的艺术纸上，鸿盛鸿彩6相对原装颜料墨水就只有色密度的差异。</p><p>主要观感差异在于光泽纸上。</p><p><strong>反光偏镜面反射，较显眼，尤其黑色墨水</strong>。但CMY墨水反光观感一致。</p><p>鸿盛鸿彩6颜料墨水的黑色墨水反光泛白的现象严重非常多，反光更偏向于镜面反射，既会成像，而爱普生原装颜料墨水会更偏向漫反射，也会成像，只是相对鸿盛更偏漫反射的感觉。</p><p><strong>镜面反射特性</strong>，优势是CMY墨水的反光观感一致，只会泛白，不会泛青铜色，避免了泛青铜色的诡异观感，但随便一个光源如吸顶灯产生的反光，都会很显眼。而相同观察位置下，吸顶灯在爱普生原装墨水上产生的反光由于偏漫反射的感觉，不是很显眼，不易感知。</p><p>而爱普生原装墨水不同颜色的墨水反光会有轻微差异。</p><p><strong>鸿盛的色密度受限，黑位有明显差距</strong>。碳黑模式甚至是负作用。</p><p>碳黑模式既在黑色墨点附近喷LGY墨水，原装墨水用以增强色密度，减轻烫金效应的影响，但在鸿盛鸿彩6墨水上更厚的膜层反而导致观感上黑位更不黑。烫金效应愈发严重。而且由于鸿盛具有兼容墨水一贯的，黑灰墨水的黑位不正的特性，启用碳黑模式需要重新校色。</p><h3 id="反光观感一致可能适合4-6色机型" tabindex="-1">反光观感一致可能适合4~6色机型 <a class="header-anchor" href="#反光观感一致可能适合4-6色机型" aria-label="Permalink to “反光观感一致可能适合4~6色机型”">​</a></h3><p>通常4~6色机型的灰阶由CMY墨水混合而成，而CMY墨水的反光观感差异，是导致其灰阶反光观感诡异的重大来源。</p><p>基于鸿盛鸿彩6墨水表现出CMY反光观感相对一致的特性，<strong>我推测</strong>，可能在4~6色机型上，鸿盛鸿彩6可能可以避免灰阶反光观感诡异，更偏向单纯的反光泛白。</p><p>黑色墨水可能考虑使用爱普生原装颜料墨盒抽墨。</p><h3 id="风险巨大" tabindex="-1">风险巨大 <a class="header-anchor" href="#风险巨大" aria-label="Permalink to “风险巨大”">​</a></h3><p>从鸿盛墨水的种种表现，<strong>我推测</strong>，鸿盛墨水可能颜料含量占比相对较低，而树脂含量占比相对较高，<strong>很可能堵头风险更大</strong>。</p><p>从爱普生P708上机鸿盛墨水的表现可见一斑，上机几个月打印头检查图就开始出状况，出现斜喷、卫星滴的现象，不过即使检查图异常，打照片一般是没有可感知的瑕疵。即使多次清洗之后打检查图正常了，也撑不了几天。</p><p>显然鸿盛鸿彩6每周打一次的维护频率是不够的，应该说只适合工商业用户。</p><p>爱普生P708有气泵，鸿盛鸿彩6的稳定性就已经不是最理想，如果要用在4~6色机型上，很可能是灾难。有多位网友反馈，鸿盛鸿彩6导致其4~6色机型打印头报废，拆下来看，打印头上都是絮状物。</p><p>桌面机型如果想要上鸿盛鸿彩6水性颜料墨水，请务必审慎。 桌面机型如果想要上鸿盛鸿彩6水性颜料墨水，请务必审慎。 桌面机型如果想要上鸿盛鸿彩6水性颜料墨水，请务必审慎。</p>`,33)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};